import React from 'react';
import * as LucideIcons from 'lucide-react';
import { HelpCircle } from 'lucide-react';

// Aceita qualquer formato de nome (kebab-case, lowercase...) — lucide.dev mostra
// nomes kebab-case pro uso vanilla, mas o pacote react exporta em PascalCase.
const toPascalCase = (str) =>
    str.replace(/[-_\s]+(.)?/g, (_, c) => (c ? c.toUpperCase() : '')).replace(/^(.)/, (c) => c.toUpperCase());

function Icon({
    name,
    size = 24,
    color = "currentColor",
    className = "",
    strokeWidth = 2,
    ...props
}) {
    const IconComponent = LucideIcons?.[name] || LucideIcons?.[toPascalCase(name ?? '')];

    if (!IconComponent) {
        return <HelpCircle size={size} color="gray" strokeWidth={strokeWidth} className={className} {...props} />;
    }

    return <IconComponent
        size={size}
        color={color}
        strokeWidth={strokeWidth}
        className={className}
        {...props}
    />;
}
export default Icon;

-- Vincula o motoboy a uma conta de cliente (Supabase Auth), quando o cadastro de
-- motoboy é feito por alguém já logado como cliente. Usado pra promover
-- user_profiles.role pra 'motoboy' automaticamente nesse caso.
ALTER TABLE public.motoboys
  ADD COLUMN IF NOT EXISTS user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_motoboys_user_id ON public.motoboys (user_id) WHERE user_id IS NOT NULL;

