1	import { BadRequestException, ConflictException, ForbiddenException, Injectable, UnauthorizedException } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	import * as bcrypt from 'bcryptjs';
4	import * as crypto from 'crypto';
5	import * as jwt from 'jsonwebtoken';
6	import { SupabaseService } from '../supabase/supabase.service';
7	import { SupabaseJwtService } from '../auth/supabase-jwt.service';
8	
9	const SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1000; // igual ao expiresIn do JWT
10	
11	// identificador/email/phone entram direto num filtro .or() do PostgREST — sem
12	// validar formato, um valor com vírgula/parênteses injeta cláusulas extras
13	// no filtro (ex. ",id.gt.0").
14	export const EMAIL_RE = /^[^\s,()]+@[^\s,()]+\.[^\s,()]+$/;
15	export const PHONE_RE = /^\+?[0-9]{8,15}$/;
16	
17	export interface CadastroMotoboyBody {
18	  name: string;
19	  phone: string;
20	  email: string;
21	  password: string;
22	  foto_perfil: string;
23	  documento_frente: string;
24	  documento_verso?: string;
25	  comprovante_endereco: string;
26	  // Token da sessão de cliente (Supabase Auth) já logada, se houver — usado
27	  // pra vincular a conta e promover user_profiles.role pra 'motoboy'.
28	  supabase_access_token?: string;
29	}
30	
31	const BUCKET = 'motoboy-documentos';
32	
33	@Injectable()
34	export class MotoboyAuthService {
35	  constructor(
36	    private supabase: SupabaseService,
37	    private config: ConfigService,
38	    private supabaseJwt: SupabaseJwtService,
39	  ) {}
40	
41	  // Motoboy e dono de estabelecimento precisam ser contas separadas — barra
42	  // ANTES de criar/vincular qualquer coisa (senão fica cadastro de motoboy
43	  // órfão se a checagem só rodasse dentro de vincularContaCliente). Regra
44	  // espelhada em OnboardingController.registrarInicial.
45	  private async exigirContaSemRestaurante(supabaseAccessToken?: string) {
46	    if (!supabaseAccessToken) return;
47	
48	    const verified = await this.supabaseJwt.verificar(supabaseAccessToken);
49	    const userId = verified?.sub;
50	    if (!userId) return;
51	
52	    const { data } = await this.supabase.client
53	      .from('restaurants')
54	      .select('id')
55	      .eq('user_id', userId)
56	      .maybeSingle();
57	    if (data) {
58	      throw new ForbiddenException('Esta conta já é de um estabelecimento. Cadastre-se como motoboy usando outra conta.');
59	    }
60	  }
61	
62	  // Se veio um token de cliente logado, vincula o motoboy a essa conta e
63	  // promove user_profiles.role pra 'motoboy' — a pessoa deixa de contar como
64	  // cliente comum a partir daqui (decisão do produto).
65	  private async vincularContaCliente(motoboyId: number, supabaseAccessToken?: string) {
66	    if (!supabaseAccessToken) return;
67	
68	    const verified = await this.supabaseJwt.verificar(supabaseAccessToken);
69	    const userId = verified?.sub;
70	    if (!userId) return;
71	
72	    await this.supabase.client.from('motoboys').update({ user_id: userId }).eq('id', motoboyId);
73	    await this.supabase.client
74	      .from('user_profiles')
75	      .update({ role: 'motoboy', updated_at: new Date().toISOString() })
76	      .eq('id', userId);
77	  }
78	
79	  private gerarToken(motoboyId: number, sessionId: string): string {
80	    const secret = this.config.getOrThrow('MOTOBOY_JWT_SECRET');
81	    return jwt.sign({ motoboyId, sessionId }, secret, { expiresIn: '30d' });
82	  }
83	
84	  // Só abre sessão nova se não houver outra ativa (ou se a anterior já expirou) —
85	  // update condicional atômico evita corrida entre dois logins simultâneos.
86	  private async abrirSessao(motoboyId: number): Promise<string> {
87	    const sessionId = crypto.randomUUID();
88	    const nowIso = new Date().toISOString();
89	    const expiresAt = new Date(Date.now() + SESSION_TTL_MS).toISOString();
90	
91	    const { data } = await this.supabase.client
92	      .from('motoboys')
93	      .update({ active_session_id: sessionId, session_expires_at: expiresAt })
94	      .eq('id', motoboyId)
95	      .or(`active_session_id.is.null,session_expires_at.lt.${nowIso}`)
96	      .select('id')
97	      .maybeSingle();
98	
99	    if (!data) {
100	      throw new ConflictException('Este motoboy já está logado em outro dispositivo. Peça pro estabelecimento liberar o acesso.');
101	    }
102	    return sessionId;
103	  }
104	
105	  private async criarSessaoEToken(motoboyId: number): Promise<string> {
106	    const sessionId = await this.abrirSessao(motoboyId);
107	    return this.gerarToken(motoboyId, sessionId);
108	  }
109	
110	  async logout(motoboyId: number) {
111	    await this.supabase.client
112	      .from('motoboys')
113	      .update({ active_session_id: null, session_expires_at: null })
114	      .eq('id', motoboyId);
115	    return { ok: true };
116	  }
117	
118	  // Bucket privado — grava o path do objeto, não a URL (URL é gerada sob demanda via signed URL).
119	  private async uploadDocumento(motoboyId: number, campo: string, base64: string): Promise<string> {
120	    const matches = base64.match(/^data:([\w/+-]+);base64,(.+)$/);
121	    const mimeType = matches ? matches[1] : 'image/jpeg';
122	    const raw = matches ? matches[2] : base64;
123	    const buffer = Buffer.from(raw, 'base64');
124	    const ext = mimeType === 'application/pdf' ? 'pdf' : mimeType === 'image/png' ? 'png' : 'jpg';
125	    const path = `${motoboyId}/${campo}-${Date.now()}.${ext}`;
126	
127	    const { error } = await this.supabase.client.storage
128	      .from(BUCKET)
129	      .upload(path, buffer, { contentType: mimeType, upsert: true });
130	    if (error) throw error;
131	
132	    return path;
133	  }
134	
135	  async cadastro(body: CadastroMotoboyBody) {
136	    await this.exigirContaSemRestaurante(body.supabase_access_token);
137	
138	    if (!body.email && !body.phone) throw new BadRequestException('Informe telefone ou e-mail');
139	    if (!body.password || body.password.length < 8) throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
140	    if (body.email && !EMAIL_RE.test(body.email)) throw new BadRequestException('E-mail inválido');
141	    if (body.phone && !PHONE_RE.test(body.phone)) throw new BadRequestException('Telefone inválido');
142	
143	    const { data: existente } = await this.supabase.client
144	      .from('motoboys')
145	      .select('id')
