  }

  // Reivindica o "slot" de sessão única pra esta conta motoboy, depois de um
  // supabase.auth.signInWithPassword() bem-sucedido no frontend.
  async abrirSessaoPortal(userId: string): Promise<{ sessionId: string }> {
