      .from('motoboys')
      .select('id, is_active')
      .eq('user_id', userId)
      .maybeSingle();
    if (!motoboy) throw new NotFoundException('Esta conta não é de um motoboy.');
    if (!motoboy.is_active) throw new ForbiddenException('Conta desativada');

    const sessionId = await this.abrirSessao(motoboy.id);
    return { sessionId };
  }
}

