    setErroSessao(null);
  } catch (e) {
    // Sessão (slot de 1 dispositivo) encerrada — pelo "forçar logout" do
    // restaurante, ou expiração natural. A conta Supabase continua válida,
    // então tenta reabrir a sessão uma vez antes de desistir.
    setErroSessao(e.message);
  } finally {
    setLoading(false);
  }
}, []);

