1	import React, { useState } from 'react';
2	import { authService } from '../../services/authService';
3	import Icon from '../AppIcon';
4	
5	// Troca de senha/email pelo próprio usuário logado — reaproveitado nos
6	// painéis admin, restaurante e cliente (só o layout ao redor muda).
7	const CredenciaisForm = ({ currentEmail }) => {
8	  const [novoEmail, setNovoEmail] = useState('');
9	  const [novaSenha, setNovaSenha] = useState('');
10	  const [confirmarSenha, setConfirmarSenha] = useState('');
11	  const [salvandoEmail, setSalvandoEmail] = useState(false);
12	  const [salvandoSenha, setSalvandoSenha] = useState(false);
13	  const [erroEmail, setErroEmail] = useState(null);
14	  const [erroSenha, setErroSenha] = useState(null);
15	  const [sucessoEmail, setSucessoEmail] = useState(false);
16	  const [sucessoSenha, setSucessoSenha] = useState(false);
17	
18	  const handleTrocarEmail = async (e) => {
19	    e.preventDefault();
20	    setErroEmail(null);
21	    setSucessoEmail(false);
22	    if (!novoEmail.trim()) return;
23	
24	    setSalvandoEmail(true);
25	    try {
26	      const resultado = await authService.updateEmail(novoEmail.trim());
27	      if (!resultado.success) {
28	        setErroEmail(resultado.error);
29	        return;
30	      }
31	      setSucessoEmail(true);
32	      setNovoEmail('');
33	    } catch {
34	      setErroEmail('Falha ao trocar email. Tente novamente.');
35	    } finally {
36	      setSalvandoEmail(false);
37	    }
38	  };
39	
40	  const handleTrocarSenha = async (e) => {
41	    e.preventDefault();
42	    setErroSenha(null);
43	    setSucessoSenha(false);
44	
45	    if (novaSenha.length < 8) {
46	      setErroSenha('Senha deve ter no mínimo 8 caracteres');
47	      return;
48	    }
49	    if (novaSenha !== confirmarSenha) {
50	      setErroSenha('Senhas não conferem');
51	      return;
52	    }
53	
54	    setSalvandoSenha(true);
55	    try {
56	      const resultado = await authService.updatePassword(novaSenha);
57	      if (!resultado.success) {
58	        setErroSenha(resultado.error);
59	        return;
60	      }
61	      setSucessoSenha(true);
62	      setNovaSenha('');
63	      setConfirmarSenha('');
64	    } catch {
65	      setErroSenha('Falha ao trocar senha. Tente novamente.');
66	    } finally {
67	      setSalvandoSenha(false);
68	    }
69	  };
70	
71	  return (
72	    <div className="space-y-6">
73	      <div className="bg-white dark:bg-zinc-800 rounded-xl border border-gray-200 dark:border-zinc-700 p-6">
74	        <h3 className="font-semibold text-gray-900 dark:text-zinc-100 mb-1">Trocar email</h3>
75	        <p className="text-sm text-gray-500 dark:text-zinc-400 mb-4">
76	          {currentEmail ? <>Email atual: <span className="font-mono">{currentEmail}</span>. </> : null}
77	          Você vai receber um link de confirmação no novo endereço antes da troca valer.
78	        </p>
79	        <form onSubmit={handleTrocarEmail} className="space-y-3">
80	          <input
81	            type="email"
82	            required
83	            placeholder="novo@email.com"
84	            value={novoEmail}
85	            onChange={(e) => setNovoEmail(e.target.value)}
86	            className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
87	          />
88	          {erroEmail && <p className="text-sm text-red-600 dark:text-red-400">{erroEmail}</p>}
89	          {sucessoEmail && (
90	            <p className="text-sm text-green-600 dark:text-green-400 flex items-center gap-1.5">
91	              <Icon name="CheckCircle" size={16} /> Verifique sua caixa de entrada para confirmar a troca.
92	            </p>
93	          )}
94	          <button
95	            type="submit"
96	            disabled={salvandoEmail}
97	            className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 disabled:opacity-50"
98	          >
99	            {salvandoEmail ? 'Enviando...' : 'Trocar email'}
100	          </button>
101	        </form>
102	      </div>
103	
104	      <div className="bg-white dark:bg-zinc-800 rounded-xl border border-gray-200 dark:border-zinc-700 p-6">
105	        <h3 className="font-semibold text-gray-900 dark:text-zinc-100 mb-1">Trocar senha</h3>
106	        <p className="text-sm text-gray-500 dark:text-zinc-400 mb-4">Mínimo de 8 caracteres.</p>
107	        <form onSubmit={handleTrocarSenha} className="space-y-3">
108	          <input
109	            type="password"
110	            required
111	            minLength={8}
112	            placeholder="Nova senha"
