const AbaPerfil = ({ me, onAtualizado }) => {
  const [form, setForm] = useState({ name: me?.name ?? '', phone: me?.phone ?? '' });
  const [foto, setFoto] = useState(null);
  const [salvando, setSalvando] = useState(false);
  const [erro, setErro] = useState(null);
  const [sucesso, setSucesso] = useState(false);
  const [enviandoReset, setEnviandoReset] = useState(false);
  const [resetEnviado, setResetEnviado] = useState(false);

  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  const handleFoto = async (file) => {
    if (!file) return;
    setFoto(await arquivoParaBase64(file));
  };

  const handleSalvar = async (e) => {
    e.preventDefault();
    setErro(null);
    setSucesso(false);
    setSalvando(true);
    try {
      const dados = { name: form.name, phone: form.phone };
      if (foto) dados.foto_perfil = foto;
      await atualizarPerfil(dados);
      setFoto(null);
      setSucesso(true);
      await onAtualizado();
    } catch (err) {
      setErro(err.message);
    } finally {
      setSalvando(false);
    }
  };

  const handleTrocarSenha = async () => {
    if (!me?.email) return;
    setEnviandoReset(true);
    try {
      await authService.resetPassword(me.email);
      setResetEnviado(true);
    } finally {
      setEnviandoReset(false);
    }
  };

  return (
    <div className="space-y-4">
      <div className="bg-white rounded-2xl border border-[#E4E4E7] p-4">
        <p className="text-xs font-bold text-[#71717A] uppercase mb-3">Meu perfil</p>
        <form onSubmit={handleSalvar} className="space-y-3">
          <div>
            <label className="block text-xs text-[#71717A] mb-1">Nome</label>
            <input value={form.name} onChange={(e) => set('name', e.target.value)} required
              className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
          </div>
          <div>
            <label className="block text-xs text-[#71717A] mb-1">Telefone</label>
            <input value={form.phone} onChange={(e) => set('phone', e.target.value)}
              className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
          </div>
          <div>
            <label className="block text-xs text-[#71717A] mb-1">E-mail</label>
            <input value={me?.email ?? ''} disabled
              className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm bg-[#F4F4F5] text-[#A1A1AA]" />
          </div>
          {CAMPOS_ARQUIVO_PERFIL.map((campo) => (
            <label key={campo.name}
              className="flex items-center gap-3 border border-dashed border-[#E4E4E7] rounded-xl px-3 py-2.5 cursor-pointer hover:border-[#FF441F]/50">
              <Icon name={foto ? 'CheckCircle2' : campo.icon} size={18} className={foto ? 'text-green-600' : 'text-[#71717A]'} />
              <span className="flex-1 text-sm text-[#27272A] truncate">{foto ? 'Nova foto selecionada' : `Trocar ${campo.label.toLowerCase()}`}</span>
              <input type="file" accept={campo.accept} className="hidden" onChange={(e) => handleFoto(e.target.files?.[0])} />
            </label>
          ))}
          {erro && <p className="text-xs text-red-600 bg-red-50 rounded-lg px-3 py-2">{erro}</p>}
          {sucesso && <p className="text-xs text-green-700 bg-green-50 rounded-lg px-3 py-2">Perfil atualizado.</p>}
          <button type="submit" disabled={salvando}
            className="w-full py-3 bg-[#FF441F] text-white font-bold rounded-xl hover:bg-[#E63A19] disabled:opacity-50 text-sm">
            {salvando ? 'Salvando...' : 'Salvar alterações'}
          </button>
        </form>
      </div>

      <div className="bg-white rounded-2xl border border-[#E4E4E7] p-4">
        <p className="text-xs font-bold text-[#71717A] uppercase mb-2">Senha</p>
        {resetEnviado ? (
          <p className="text-xs text-green-700 bg-green-50 rounded-lg px-3 py-2">
            Enviamos um link pro seu e-mail pra você definir uma nova senha.
          </p>
        ) : (
          <button onClick={handleTrocarSenha} disabled={enviandoReset}
            className="w-full py-2.5 border border-[#E4E4E7] text-[#27272A] text-sm font-semibold rounded-xl hover:bg-[#F4F4F5] disabled:opacity-50">
            {enviandoReset ? 'Enviando...' : 'Enviar link para trocar senha'}
          </button>
        )}
      </div>
    </div>
  );
};

